// Unedit Pro: the graphics pass over a one-take clip. Unedit (genovus.io) cuts a clean 9:16 clip with ffmpeg (no
// captions) and plans one shot per sentence; this composition lays each shot out in the Genovus look and draws the
// captions itself, so a caption never shrinks with the speaker when the speaker moves into a card or a bubble.
//   face    the speaker full frame                     card    the speaker in a card on the light canvas
//   screen  a real Genovus screen, speaker in a bubble  split   speaker above; a screen or a figure below
//   number  one big figure from the talk               word    the accent word, huge
// The speaker's audio plays once, start to finish; every picture of the speaker is the same clip, muted and in sync.
// Props come from Unedit (lib/unedit-pro.ts); screens are presigned links to the screen library's real captures.
import React from 'react';
import { AbsoluteFill, Audio, continueRender, delayRender, Img, interpolate, staticFile, OffthreadVideo, Sequence, spring, useCurrentFrame, useVideoConfig, type CalculateMetadataFunction } from 'remotion';
import { C, F } from './brand';
import { CameraRig, CueLayer, CueSounds, CutLeaks, Grain, type ProCue } from './UneditCues';

export type ProLayout = 'face' | 'card' | 'screen' | 'split' | 'number' | 'word';
export type ProWord = { w: string; s: number; e: number; a?: boolean };
export type ProShot = { s: number; e: number; layout: ProLayout; accent?: string | null; figure?: string | null; screen?: { still: string; clip?: string | null; wide?: boolean } | null };
export type UneditProProps = { src: string; secs: number; words: ProWord[]; shots: ProShot[]; cues?: ProCue[]; serif?: boolean; sfx?: boolean };

export const PRO_FPS = 30;
const CANVAS = '#F6F4F1';
const INK = '#14161B';
const ACCENT = '#FF6A2B';
const GOLD = '#FFA31A';
const SERIF = '"Instrument Serif", Georgia, serif';
// The accent face (Instrument Serif Italic, SIL OFL 1.1; license in public-pro/fonts). Loaded before the first frame.
if (typeof document !== 'undefined') {
  const h = delayRender('accent serif');
  new FontFace('Instrument Serif', `url(${staticFile('fonts/instrument-serif-italic.ttf')})`, { style: 'italic', weight: '400' }).load()
    .then((f) => { document.fonts.add(f); continueRender(h); })
    .catch((e) => { console.error(e); continueRender(h); });
}

export const calculateProMetadata: CalculateMetadataFunction<UneditProProps> = ({ props }) => ({
  durationInFrames: Math.max(1, Math.round(props.secs * PRO_FPS)),
  fps: PRO_FPS, width: 1080, height: 1920,
});

/** The speaker, muted and in sync with the clip (the audio track plays separately). */
function Speaker({ src, from, style }: { src: string; from: number; style?: React.CSSProperties }) {
  return <OffthreadVideo src={src} muted startFrom={from} style={{ width: '100%', height: '100%', objectFit: 'cover', ...style }} />;
}

/** A shot's entrance: a quick settle in scale and opacity over its first frames. */
function useEnter() {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = spring({ frame, fps, config: { damping: 18, stiffness: 160, mass: 0.7 } });
  return { p, style: { opacity: interpolate(p, [0, 1], [0, 1]), transform: `scale(${interpolate(p, [0, 1], [1.04, 1])})` } };
}

function ScreenInsert({ screen, from }: { screen: NonNullable<ProShot['screen']>; from: number }) {
  // A slow push-in keeps a screen alive while it holds. A wide (desktop) capture is cropped from its top-left corner
  // (the menu and the start of each line) at a readable size, instead of from its middle or shrunk to fit.
  const frame = useCurrentFrame();
  const push = interpolate(frame, [0, 8 * PRO_FPS], [1, 1.08], { extrapolateRight: 'clamp' });
  const fit: React.CSSProperties = { width: '100%', height: '100%', objectFit: 'cover', objectPosition: screen.wide ? 'left top' : 'top', transform: `scale(${push})`, transformOrigin: screen.wide ? '0% 0%' : '50% 20%' };
  return screen.clip
    ? <OffthreadVideo src={screen.clip} muted startFrom={0} style={fit} />
    : <Img src={screen.still} style={fit} key={from} />;
}

/** The speaker in a round bubble, placed clear of the captions (which sit low on the frame). */
function Bubble({ src, from, top = 110, size = 300 }: { src: string; from: number; top?: number; size?: number }) {
  return (
    <div style={{ position: 'absolute', right: 70, top, width: size, height: size, borderRadius: '50%', overflow: 'hidden', border: '8px solid #fff', boxShadow: '0 24px 60px rgba(0,0,0,.55)' }}>
      <Speaker src={src} from={from} />
    </div>
  );
}

function Shot({ shot, src, from }: { shot: ProShot; src: string; from: number }) {
  const { style, p } = useEnter();
  switch (shot.layout) {
    case 'card':
      return (
        <AbsoluteFill style={{ background: CANVAS }}>
          <div style={{ position: 'absolute', left: 110, right: 110, top: 230, height: 1075, borderRadius: 48, overflow: 'hidden', boxShadow: '0 40px 90px -30px rgba(0,0,0,.45)', ...style }}>
            <Speaker src={src} from={from} />
          </div>
        </AbsoluteFill>
      );
    case 'screen':
      return (
        <AbsoluteFill style={{ background: C.bg }}>
          <div style={{ position: 'absolute', left: 60, right: 60, top: 120, bottom: 640, borderRadius: 40, overflow: 'hidden', border: `2px solid ${C.line}`, background: C.panel, ...style }}>
            {shot.screen ? <ScreenInsert screen={shot.screen} from={from} /> : null}
          </div>
          <Bubble src={src} from={from} top={1110} size={280} />
        </AbsoluteFill>
      );
    case 'split':
      return (
        <AbsoluteFill style={{ background: C.bg }}>
          <div style={{ position: 'absolute', left: 0, right: 0, top: 0, height: 960, overflow: 'hidden' }}><Speaker src={src} from={from} /></div>
          <div style={{ position: 'absolute', left: 0, right: 0, top: 960, bottom: 0, borderTop: `6px solid ${ACCENT}`, background: C.panel, overflow: 'hidden', ...style }}>
            {shot.screen ? <ScreenInsert screen={shot.screen} from={from} /> : (
              <div style={{ display: 'grid', placeItems: 'center', height: '100%', fontFamily: F.display, fontWeight: 800, fontSize: 220, color: '#fff', letterSpacing: '-0.02em' }}>{shot.figure}</div>
            )}
          </div>
        </AbsoluteFill>
      );
    case 'number':
      return (
        <AbsoluteFill style={{ background: CANVAS }}>
          <div style={{ position: 'absolute', left: 60, right: 60, top: 420, textAlign: 'center', fontFamily: F.display, fontWeight: 800, fontSize: (shot.figure ?? '').length > 5 ? 200 : 300, lineHeight: 1, color: INK, letterSpacing: '-0.03em', ...style }}>
            {shot.figure}
          </div>
          <Bubble src={src} from={from} top={800} size={320} />
        </AbsoluteFill>
      );
    case 'word': {
      const word = (shot.accent ?? '').replace(/[^\p{L}\p{N}$%.'-]/gu, '');
      return (
        <AbsoluteFill style={{ background: C.bg, display: 'grid', placeItems: 'center' }}>
          <div style={{ transform: `translateY(${interpolate(p, [0, 1], [60, 0])}px)`, opacity: p, textAlign: 'center', padding: '0 80px' }}>
            <span style={{ fontFamily: SERIF, fontStyle: 'italic', fontSize: word.length > 9 ? 170 : 230, lineHeight: 1, color: ACCENT }}>{word.toLowerCase()}</span>
          </div>
          <Bubble src={src} from={from} top={150} size={260} />
        </AbsoluteFill>
      );
    }
    default:
      return <AbsoluteFill style={{ background: '#000' }}><Speaker src={src} from={from} /></AbsoluteFill>;
  }
}

/** Phrases of up to three words (a new one after a sentence end or a pause), as in the ffmpeg captions. */
function phrases(words: ProWord[]): ProWord[][] {
  const out: ProWord[][] = [];
  let cur: ProWord[] = [];
  words.forEach((w, i) => {
    const prev = words[i - 1];
    if (cur.length && (cur.length >= 3 || (prev && (/[.!?]$/.test(prev.w) || w.s - prev.e > 0.6)))) { out.push(cur); cur = []; }
    cur.push(w);
  });
  if (cur.length) out.push(cur);
  return out;
}

/** The Genovus caption: words light up as they are spoken; the accent word is italic serif in Genovus orange. */
function Captions({ words, shots, serif }: { words: ProWord[]; shots: ProShot[]; serif: boolean }) {
  const frame = useCurrentFrame();
  const t = frame / PRO_FPS;
  const list = React.useMemo(() => phrases(words), [words]);
  const cur = list.find((p, i) => t >= p[0].s && t < Math.min(Math.max(p[p.length - 1].e + 0.25, p[0].s + 0.5), list[i + 1]?.[0].s ?? Infinity));
  if (!cur) return null;
  // The shot on screen: the last one that has started (the gap after a sentence still shows that sentence's shot).
  const shot = [...shots].reverse().find((s) => t >= s.s) ?? shots[0];
  const light = shot && (shot.layout === 'card' || shot.layout === 'number');
  // On a split the caption sits over the speaker's half, just above the seam, so it never covers the screen.
  const bottom = shot?.layout === 'card' ? 330 : shot?.layout === 'split' ? 1000 : shot?.layout === 'screen' ? 330 : 470;
  return (
    <AbsoluteFill style={{ pointerEvents: 'none' }}>
      <div style={{ position: 'absolute', left: 90, right: 90, bottom, textAlign: 'center', fontFamily: F.display, fontWeight: 800, fontSize: 84, lineHeight: 1.12, textTransform: 'uppercase', textWrap: 'balance' }}>
        {cur.map((w, k) => {
          const said = t >= w.s;
          const base: React.CSSProperties = { color: light ? INK : said ? GOLD : '#fff', opacity: light && !said && !w.a ? 0.38 : 1, textShadow: light ? 'none' : '0 4px 18px rgba(0,0,0,.75), 0 0 2px rgba(0,0,0,.9)', WebkitTextStroke: light ? undefined : '3px rgba(0,0,0,.85)', paintOrder: 'stroke fill' };
          const accent: React.CSSProperties = serif
            ? { fontFamily: SERIF, fontStyle: 'italic', fontWeight: 400, textTransform: 'none', fontSize: 108, color: ACCENT, WebkitTextStroke: light ? undefined : '2px rgba(0,0,0,.6)' }
            : { color: ACCENT, fontSize: 94 };
          return <span key={`${w.s}-${k}`} style={{ ...base, ...(w.a ? accent : {}) }}>{k ? ' ' : ''}{w.a && serif ? w.w.toLowerCase() : w.w}</span>;
        })}
      </div>
    </AbsoluteFill>
  );
}

// Sound effects (synthesized for Genovus with ffmpeg, so there is no license to track; public-pro/sfx): a soft whoosh
// that peaks on each change of layout, and a quiet pop on an accent word that isn't already next to a whoosh. Both
// sit well under the voice, and never more than one every SFX_GAP seconds, so they mark the edit without crowding it.
const WHOOSH_PEAK = 0.25; // seconds into whoosh.wav where it is loudest
const SFX_GAP = 0.7;
export function sfxCues(words: ProWord[], sorted: ProShot[], busy: number[] = []): { t: number; kind: 'whoosh' | 'pop' }[] {
  const cues: { t: number; kind: 'whoosh' | 'pop' }[] = [];
  for (let i = 1; i < sorted.length; i++) if (sorted[i].layout !== sorted[i - 1].layout) cues.push({ t: sorted[i].s, kind: 'whoosh' });
  let lastPop = -Infinity;
  for (const w of words) {
    if (!w.a || w.s - lastPop < 1.5 || cues.some((c) => Math.abs(c.t - w.s) < SFX_GAP)) continue;
    cues.push({ t: w.s, kind: 'pop' });
    lastPop = w.s;
  }
  // A cue's own sound owns its moment: no layout whoosh or accent pop within SFX_GAP of it.
  return cues.filter((c) => !busy.some((t) => Math.abs(t - c.t) < SFX_GAP)).sort((a, b) => a.t - b.t);
}

function SoundEffects({ words, shots, busy }: { words: ProWord[]; shots: ProShot[]; busy: number[] }) {
  return <>{sfxCues(words, shots, busy).map((c, i) => {
    const at = c.kind === 'whoosh' ? c.t - WHOOSH_PEAK : c.t;
    return <Sequence key={i} from={Math.max(0, Math.round(at * PRO_FPS))} durationInFrames={Math.round(0.6 * PRO_FPS)} name={`sfx ${c.kind}`}>
      <Audio src={staticFile(`sfx/${c.kind}.wav`)} volume={c.kind === 'whoosh' ? 0.45 : 0.3} />
    </Sequence>;
  })}</>;
}

export const UneditPro: React.FC<UneditProProps> = ({ src, words, shots, cues = [], serif = false, sfx = false }) => {
  const sorted = [...shots].sort((a, b) => a.s - b.s);
  return (
    <AbsoluteFill style={{ background: '#000' }}>
      <CameraRig cues={cues}>
        {sorted.map((sh, i) => {
          const from = i === 0 ? 0 : Math.round(sh.s * PRO_FPS);
          const to = Math.round((sorted[i + 1]?.s ?? Infinity) * PRO_FPS);
          const dur = Number.isFinite(to) ? Math.max(1, to - from) : undefined;
          return <Sequence key={i} from={from} durationInFrames={dur} name={`${i + 1} ${sh.layout}`}><Shot shot={sh} src={src} from={from} /></Sequence>;
        })}
      </CameraRig>
      <CutLeaks cuts={sorted.filter((sh, i) => i > 0 && sh.layout !== sorted[i - 1].layout && (sh.layout === 'screen' || sorted[i - 1].layout === 'screen')).map((sh) => sh.s)} fps={PRO_FPS} />
      <CueLayer cues={cues} fps={PRO_FPS} />
      <Grain />
      <Captions words={words} shots={sorted} serif={serif} />
      <Audio src={src} />
      {sfx && <SoundEffects words={words} shots={sorted} busy={cues.filter((c) => c.sound).map((c) => c.t)} />}
      {sfx && <CueSounds cues={cues} fps={PRO_FPS} />}
    </AbsoluteFill>
  );
};
